<?php
namespace App\Http\Controllers; use App\Models\{Order, Payment}; use App\Services\PaymentService; use Illuminate\Http\{JsonResponse, RedirectResponse, Request}; class PaymentController extends Controller { public function invoice(Order $order, PaymentService $payments): RedirectResponse { $this->authorize('view',$order); $payments->createInvoice($order); return back()->with('success','Invoice generated.'); } public function verify(Payment $payment, PaymentService $payments): RedirectResponse { $this->authorize('assign', \App\Models\Order::class); $payments->markPaid($payment); return back()->with('success','Payment verified.'); } public function webhook(Request $request, PaymentService $payments): JsonResponse { $payments->handleMidtransWebhook($request->all()); return response()->json(['ok'=>true]); } }
